css:
.fx-sc{width:min(900px,100%);display:grid;gap:clamp(1.6em,5vw,2.6em)}
.fx-sc .eye{font-size:.78em;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--accent)}
.fx-sc h2{font-size:clamp(2.2em,6vw,4.4em);line-height:1.05;letter-spacing:-.02em}
.fx-sc .lead{max-width:34em;opacity:.72;font-size:1.05em}
.sc-list{list-style:none;margin:0;padding:0;border-top:1px solid var(--border)}
.sc-list li{border-bottom:1px solid var(--border)}
.sc-list a{display:grid;grid-template-columns:3em minmax(0,1fr) auto;gap:1em;align-items:baseline;padding:1em .2em;color:inherit;text-decoration:none}
.sc-list a:focus-visible{outline:3px solid var(--accent);outline-offset:-3px}
.sc-list .no{font:600 .8em var(--font-heading);letter-spacing:.14em;color:var(--accent)}
.sc-list .t{font:600 clamp(1.3em,3vw,2em) var(--font-heading)}.sc-list .d{opacity:.55;font-size:.88em}
.fx-sc .rp{justify-self:start;border:2px solid var(--primary);background:transparent;color:var(--primary);border-radius:99px;padding:.6em 1.3em;font:700 .9em var(--font-body);cursor:pointer}
.fx-sc .rp:hover,.fx-sc .rp.is-tap{background:var(--primary);color:var(--on-primary)}.fx-sc .rp:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.sc-sr{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0}
.sc-w{white-space:nowrap}
.sc-c.sc-u{color:var(--accent);opacity:.85;display:inline-block;text-align:center;overflow:visible}
@media(max-width:700px){.sc-list a{grid-template-columns:2.4em minmax(0,1fr)}.sc-list .d{display:none}}

